// test.c - generated by split_c.py from test.c
#include "test_priv.h"



//*****************************************************************************
// Mode switching (logic only: draws happen in Render via s_dirtyFull)
//*****************************************************************************
static void EnterMode(uint16_t mode)
{
    uint16_t i;

    test_mode      = mode;
    test_dirtyFull = true;

    if(mode == MODE_INPUT)
    {
        test_jx = test_jy = test_lastX = test_lastY = test_prX = test_prY = 0;
        test_drawDotX  = test_drawRingX = TEST_BOX_CX;
        test_drawDotY  = test_drawRingY = TEST_BOX_CY;
        for(i = 0; i < PAD_COUNT; i++)
        {
            test_lit[i]      = 0;
            test_litShown[i] = 0xFFFF;                 // force the first draw
        }
    }
    else if(mode == MODE_SOUND)
    {
        test_sndRow  = ROW_SONG;
        test_musicOn = 0;
    }
}


//*****************************************************************************
// init: runs once when the app starts.
//*****************************************************************************
static void Test_Init(void)
{
    test_frames  = 0;
    test_stX     = 0;
    test_stY     = 0;
    test_menuSel = 0;
    test_sfxIdx  = 0;
    test_dirtyRow = 0;

    Buzzer_Stop();
    EnterMode(MODE_MENU);               // Render draws it on the first frame
}


//*****************************************************************************
// update: once per frame. LOGIC ONLY.
//*****************************************************************************
static AppStatus Test_UpdateMenu(int16_t sy)
{
    if(g_dpad.rPressed)
        return APP_QUIT;

    if(sy != 0)
    {
        uint16_t sel = (sy > 0) ? 1 : 0;        // down = second item
        if(sel != test_menuSel)
        {
            test_menuSel  = sel;
            test_dirtyRow = 0x03;                  // redraw both rows
        }
    }

    if(g_dpad.dPressed || g_joy.btnPressed)
        EnterMode(test_menuSel ? MODE_SOUND : MODE_INPUT);

    return APP_CONTINUE;
}


static AppStatus Test_UpdateInput(void)
{
    uint16_t i;
    bool     changed;

    // Joystick + prediction (linear extrapolation of the last step).
    test_lastX = test_jx;
    test_lastY = test_jy;
    test_jx    = g_joy.dx;
    test_jy    = g_joy.dy;

    {
        int16_t px = test_Clamp16(test_jx + TEST_PRED_GAIN * (test_jx - test_lastX), -100, 100);
        int16_t py = test_Clamp16(test_jy + TEST_PRED_GAIN * (test_jy - test_lastY), -100, 100);

        changed = (px != test_prX) || (py != test_prY) ||
                  (test_jx != test_lastX) || (test_jy != test_lastY);
        test_prX = px;
        test_prY = py;
    }

    if(changed) test_dirtyStick = true;
    if(test_jx != test_lastX || test_jy != test_lastY) test_dirtyReadout = true;

    // Buttons: count down, then re-arm on this frame's edges.
    for(i = 0; i < PAD_COUNT; i++)
        if(test_lit[i]) test_lit[i]--;

    if(TEST_PAD_U)        test_lit[0]       = TEST_PAD_LIT_FRAMES;
    if(TEST_PAD_L)        test_lit[1]       = TEST_PAD_LIT_FRAMES;
    if(TEST_PAD_R)        test_lit[2]       = TEST_PAD_LIT_FRAMES;
    if(TEST_PAD_D)        test_lit[3]       = TEST_PAD_LIT_FRAMES;
    if(g_joy.btnPressed)  test_lit[PAD_STK] = TEST_PAD_LIT_FRAMES;

    for(i = 0; i < PAD_COUNT; i++)
        if((test_lit[i] != 0) != (bool)test_litShown[i]) test_dirtyPads = true;

    // R + D pressed together (both edges within TEST_CHORD_SLACK frames) = back.
    if(test_lit[2] >= TEST_PAD_LIT_FRAMES - TEST_CHORD_SLACK &&
       test_lit[3] >= TEST_PAD_LIT_FRAMES - TEST_CHORD_SLACK)
        EnterMode(MODE_MENU);

    return APP_CONTINUE;
}


static void Test_SndChange(int16_t dir)
{
    uint16_t level;

    switch(test_sndRow)
    {
        case ROW_SONG:
            test_songIdx = (uint16_t)((test_songIdx + (dir > 0 ? 1 : numSongs - 1)) % numSongs);
            if(test_musicOn) Buzzer_PlaySong(songList[test_songIdx], 1);
            test_dirtyRow |= (1 << ROW_SONG);
            break;

        case ROW_SFX:
            test_sfxIdx = (uint16_t)((test_sfxIdx + (dir > 0 ? 1 : NUM_SFX - 1)) % NUM_SFX);
            test_dirtyRow |= (1 << ROW_SFX);
            break;

        default:                                // ROW_VOL
            level = Buzzer_GetVolume();
            if(dir > 0 && level < BUZZER_NUM_VOLUMES - 1) level++;
            if(dir < 0 && level > 0)                      level--;
            Buzzer_SetVolume(level);
            if(!Buzzer_IsPlaying())             // nothing to hear the change on: beep
                Buzzer_PlaySfx(&sfx_coin);
            test_dirtyRow |= (1 << ROW_VOL) | DIRTY_BARS;
            break;
    }
}


static AppStatus Test_UpdateSound(int16_t sx, int16_t sy)
{
    if(g_dpad.rPressed)
    {
        Buzzer_Stop();
        EnterMode(MODE_MENU);
        return APP_CONTINUE;
    }

    if(sy != 0)                                 // change row (wraps)
    {
        test_dirtyRow |= (1 << test_sndRow) | DIRTY_BARS;
        test_sndRow = (sy > 0) ? (test_sndRow + 1) % SND_ROWS
                            : (test_sndRow + SND_ROWS - 1) % SND_ROWS;
        test_dirtyRow |= (1 << test_sndRow);
    }

    if(sx != 0)
        Test_SndChange(sx);

    if(g_dpad.dPressed)
    {
        switch(test_sndRow)
        {
            case ROW_SONG:
                Buzzer_PlaySong(songList[test_songIdx], 1);
                test_musicOn = 1;
                break;
            case ROW_SFX:
                Buzzer_PlaySfx(test_kSfx[test_sfxIdx]);
                break;
            default:
                Buzzer_PlaySfx(&sfx_coin);
                break;
        }
    }

    if(g_joy.btnPressed)
    {
        Buzzer_Stop();
        test_musicOn = 0;
    }

    return APP_CONTINUE;
}


static AppStatus Test_Update(void)
{
    int16_t sx = test_StickEdge(g_joy.dx, &test_stX);
    int16_t sy = test_StickEdge(g_joy.dy, &test_stY);

    test_frames++;

    switch(test_mode)
    {
        case MODE_INPUT: return Test_UpdateInput();
        case MODE_SOUND: return Test_UpdateSound(sx, sy);
        default:         return Test_UpdateMenu(sy);
    }
}


//*****************************************************************************
// render: once per frame. DRAWING ONLY.
//*****************************************************************************
static void Test_Render(void)
{
    uint16_t i;
    bool     full = test_dirtyFull;

    if(full)
    {
        test_dirtyFull = false;

        if(test_mode == MODE_INPUT)
        {
            test_DrawInputStatic();
            test_dirtyStick = test_dirtyPads = test_dirtyReadout = true;
        }
        else if(test_mode == MODE_SOUND)
        {
            test_DrawTitle("Sound");
            test_DrawText("Stick: pick / change", SCREEN_W / 2, 52, COLOR_GRAY, false);
            test_DrawHint("D:play Btn:stop R:back");
            test_dirtyRow = 0x0F;
        }
        else
        {
            test_DrawTitle("TEST APP");
            test_DrawHint("Stick: pick  D: open");
            test_dirtyRow = 0x03;
        }
    }

    if(test_mode == MODE_INPUT)
    {
        if(test_dirtyStick)
        {
            test_DrawStick();
            test_dirtyStick = false;
        }

        // Text is the slowest thing here: at most every 3rd frame.
        if(test_dirtyReadout && (full || (test_frames % 3) == 0))
        {
            test_DrawReadout();
            test_dirtyReadout = false;
        }

        if(test_dirtyPads)
        {
            for(i = 0; i < PAD_COUNT; i++)
            {
                uint16_t lit = (test_lit[i] != 0);
                if(lit != test_litShown[i])
                {
                    test_DrawPad(i, lit);
                    test_litShown[i] = lit;
                }
            }
            test_dirtyPads = false;
        }
    }
    else if(test_mode == MODE_SOUND)
    {
        for(i = 0; i < SND_ROWS; i++)
            if(test_dirtyRow & (1 << i)) test_DrawSndRow(i);
        if(test_dirtyRow & DIRTY_BARS) test_DrawBars();
        test_dirtyRow = 0;
    }
    else
    {
        for(i = 0; i < MENU_ITEMS; i++)
            if(test_dirtyRow & (1 << i)) test_DrawMenuRow(i);
        test_dirtyRow = 0;
    }
}


//*****************************************************************************
// exit: leaving the app silences the buzzer.
//*****************************************************************************
static void Test_Exit(void)
{
    Buzzer_Stop();
}


//*****************************************************************************
// The app descriptor: the ONLY public symbol in this file.
//*****************************************************************************
const App g_testApp =
{
    "TEST",                             // name (first letter = menu tile icon)
    "Input and sound tests",            // hint shown under the menu
    COLOR_CYAN,                         // menu tile color
    TEST_FRAME_US,                      // frame period
    Test_Init, Test_Update, Test_Render,
    Test_Exit,
    NULL                                // not a legacy app
};
